  /* Accountant hand-over (gap round 2026-11-14) */
  "nav.ca": "Accountant viewer",
  "ca.mk": "Make a file for my accountant (read-only)",
  "ca.t": "File for my accountant",
  "ca.intro": "Packs one business and period into ONE read-only file (.nsca). Send it to your accountant by WhatsApp or email. They open it on ca.niveshsahayak.in, read the books, add queries and send comments back to you.",
  "ca.notlive": "This is a file hand-over, not a live shared login. Your accountant sees the books as they were when you made the file. A live login would need a server that stores your books, and Nivesh Sahayak has none: your books stay on your device. For newer entries, make a new file.",
  "ca.what": "What goes in",
  "ca.earlier": "Entries before the first date too (needed for opening balances and ageing)",
  "ca.items": "Item list with purchase and sale rates (needed for stock)",
  "ca.extra": "Only if you tick it",
  "ca.extrah": "Left out unless you tick. Pictures (logo, signature), your PIN and the backup settings are never included.",
  "ca.orders": "Quotations, proforma invoices, sales orders, challans and purchase orders",
  "ca.staff": "Salary slips, staff advances, loans and EMIs, petty cash, and the employee list",
  "ca.phones": "Phone numbers, e-mail addresses and WhatsApp numbers of parties",
  "ca.bank": "Your own bank account number, IFSC and UPI id",
  "ca.no.orders": "quotations and orders",
  "ca.no.staff": "salary and staff records",
  "ca.no.phones": "phone numbers and e-mail addresses",
  "ca.no.bank": "your bank account details",
  "ca.note": "A note for your accountant (optional)",
  "ca.go": "Make the file",
  "ca.ready": "File ready: {n} entries, {p} parties, about {kb} KB.",
  "ca.code": "Check code:",
  "ca.codeh": "Send this code in your message, or read it out on a call. Your accountant compares it with the code the file shows, so a file changed on the way is noticed.",
  "ca.notin": "Not in this file: {w}.",
  "ca.nothing": "nothing was left out",
  "ca.copymsg": "Copy the message",
  "ca.copied": "Message copied",
  "ca.msgl": "Message to send with the file",
  "ca.msg": "Books of {biz} from {from} to {to}. Open the attached file on {url} (works without login, nothing is uploaded). Check code: {code}. This is a read-only copy made today; please send your queries back as a comments file.",
  "ca.how": "Send the file by WhatsApp or e-mail as an attachment. If WhatsApp shows the name with .nsca at the end, do not rename it.",
  "ca.cT": "CA comments",
  "ca.cIntro": "Your accountant sends back a small file of queries and comments (.nsca-comments). Load it here to see each query beside the entry it is about. Reply, mark it closed, and save the file again to send it back.",
  "ca.load": "Load comments file",
  "ca.export": "Save file with my replies",
  "ca.loaded": "{a} new, {c} updated",
  "ca.unsealed": "This file has no checksum, so a change on the way would not show.",
  "ca.badfile": "This is not a comments file from the accountant viewer, or it was changed.",
  "ca.openn": "{n} open",
