  "it.b1": "ꯔꯦꯠꯁꯤꯡ ({d} ꯒꯤ ꯑꯣꯏꯅ), ꯇꯦꯛꯁ ꯆꯍꯤ 2026-27: ꯑꯅꯧꯕ ꯔꯤꯖꯤꯝ ₹4 lakh ꯐꯥꯑꯣꯕ nil, ₹8 lakh ꯐꯥꯑꯣꯕ 5%, ₹12 lakh ꯐꯥꯑꯣꯕ 10%, ₹16 lakh ꯐꯥꯑꯣꯕ 15%, ₹20 lakh ꯐꯥꯑꯣꯕ 20%, ₹24 lakh ꯐꯥꯑꯣꯕ 25%, ꯃꯗꯨꯗꯒꯤ ꯍꯦꯟꯕꯗ 30%; ₹12 lakh ꯐꯥꯑꯣꯕ ꯏꯅꯀꯃꯗ ꯇꯦꯛꯁ ꯂꯩꯇꯅꯕ ꯔꯤꯕꯦꯠ, ꯃꯗꯨꯒꯤ ꯃꯊꯛꯇ ꯈꯔꯥ ꯍꯦꯟꯕꯗ ꯃꯥꯔꯖꯤꯅꯦꯜ ꯔꯤꯂꯤꯐ; ꯁꯦꯂꯔꯤꯗ ꯁ꯭ꯇꯦꯟꯗꯔꯗ ꯗꯤꯗꯛꯁꯟ ₹75,000꯫ ꯑꯔꯤꯕ ꯔꯤꯖꯤꯝ: ₹2.5 lakh ꯐꯥꯑꯣꯕ nil (ꯆꯍꯤ 60 ꯗ ₹3 lakh, ꯆꯍꯤ 80 ꯗ ₹5 lakh), ₹5 lakh ꯐꯥꯑꯣꯕ 5%, ₹10 lakh ꯐꯥꯑꯣꯕ 20%, ꯃꯗꯨꯗꯒꯤ ꯍꯦꯟꯕꯗ 30%; ₹5 lakh ꯐꯥꯑꯣꯕ ꯔꯤꯕꯦꯠ ₹12,500; ꯁ꯭ꯇꯦꯟꯗꯔꯗ ꯗꯤꯗꯛꯁꯟ ₹50,000꯫ ꯃꯁꯤꯁꯤꯡ ꯁꯦꯂꯔꯤ ꯁ꯭ꯂꯤꯞ ꯇꯨꯂꯅ ꯁꯤꯖꯤꯟꯅꯔꯤꯕ ꯔꯦꯠꯁꯤꯡꯅꯤ; ꯕꯤꯜꯗ ꯑꯁꯤꯗ Finance Act ꯗꯒꯤ ꯑꯃꯨꯛ ꯍꯟꯅ ꯄꯥꯈꯤꯗꯦ, ꯃꯔꯝ ꯑꯗꯨꯅ ꯌꯦꯡꯁꯤꯟꯕꯤꯌꯨ꯫",
  "it.b2": "ꯑꯦꯗꯚꯥꯟꯁ ꯇꯦꯛꯁ (Income-tax Act 2025, sections 403 to 408): TDS ꯀꯥꯊꯣꯛꯂꯕꯥ ꯃꯇꯨꯡꯗ ꯇꯦꯛꯁ ₹10,000 ꯅꯠꯔꯒꯥ ꯃꯗꯨꯗꯒꯤ ꯍꯦꯟꯔꯕꯗ ꯄꯤꯒꯗꯕꯅꯤ; 15 June ꯐꯥꯑꯣꯕ 15%, 15 September ꯐꯥꯑꯣꯕ 45%, 15 December ꯐꯥꯑꯣꯕ 75%, 15 March ꯐꯥꯑꯣꯕ ꯄꯨꯝꯅꯃꯛ; ꯄ꯭ꯔꯤꯖꯝꯄꯇꯤꯚ ꯇꯦꯛꯁꯄꯦꯌꯔꯅ 15 March ꯐꯥꯑꯣꯕ ꯄꯨꯝꯅꯃꯛ ꯄꯤꯏ; 31 March ꯐꯥꯑꯣꯕ ꯄꯤꯔꯕ ꯑꯗꯨ ꯆꯍꯤ ꯑꯗꯨꯒꯤꯗꯃꯛ ꯃꯁꯤꯡ ꯊꯤꯏ; ꯕꯤꯖꯤꯅꯦꯁ ꯏꯅꯀꯝ ꯂꯩꯇꯕ ꯆꯍꯤ 60 ꯅꯠꯔꯒꯥ ꯍꯦꯟꯕ resident ꯑꯃ ꯀꯥꯊꯣꯛꯂꯤ꯫",
  "it.b3": "ꯏꯟꯇꯔꯦꯁ꯭ꯠ: section 424 (ꯑꯔꯤꯕ 234B) ꯑꯁꯤ ꯇꯦꯛꯁꯀꯤ 90% ꯗꯒꯤ ꯍꯟꯅ ꯄꯤꯔꯕꯗ ꯍꯟꯊꯔꯕ ꯑꯗꯨꯗ ꯊꯥ ꯑꯃ ꯅꯠꯔꯒꯥ ꯊꯥꯒꯤ ꯁꯔꯨꯛ ꯑꯃꯗ 1% ꯅꯤ; section 425 (ꯑꯔꯤꯕ 234C) ꯑꯁꯤ ꯑꯍꯥꯅꯕ ꯏꯟꯁ꯭ꯇꯣꯂꯃꯦꯟꯠ ꯑꯍꯨꯝ ꯈꯨꯗꯤꯡꯒꯤ ꯍꯟꯊꯔꯕꯗ 3% (15 June ꯐꯥꯑꯣꯕ 12% ꯑꯃꯁꯨꯡ 15 September ꯐꯥꯑꯣꯕ 36% ꯄꯤꯔꯕꯗꯤ ꯂꯩꯇꯦ) ꯑꯃꯁꯨꯡ March ꯒꯤ ꯍꯟꯊꯔꯕꯗ 1% ꯅꯤ꯫",
  "it.b4": "ꯃꯊꯛꯇ ꯂꯩꯕ sections ꯑꯁꯤꯁꯤꯡ 15 Nov 2026 ꯗ Income Tax Department ꯒꯤ ꯋꯦꯕꯁꯥꯏꯠ (incometaxindia.gov.in) ꯗ ꯂꯩꯕ ꯑꯣꯐꯤꯁꯤꯌꯦꯜ ꯇꯦꯛꯁꯇꯀꯥ ꯋꯥꯍꯩ ꯈꯨꯗꯤꯡ ꯌꯦꯡꯁꯤꯟꯈꯤ꯫ ꯄ꯭ꯔꯤꯟꯠ ꯇꯧꯔꯕ Act ꯑꯗꯨꯅ ꯂꯦꯞꯄꯤ꯫",
  "it.b5": "ꯂꯥꯏꯔꯤꯛꯀꯤ ꯀꯥꯟꯅꯕ ꯑꯁꯤ ꯇꯦꯛꯁ ꯂꯩꯕ ꯀꯥꯟꯅꯕ ꯅꯠꯇꯦ: Act ꯒꯤ ꯃꯈꯥꯗ ꯗꯤꯞꯔꯤꯁꯤꯌꯦꯁꯟ, ꯌꯥꯗꯕ ꯁꯦꯟꯊꯣꯛ ꯑꯃꯁꯨꯡ ꯄ꯭ꯔꯤꯖꯝꯄꯇꯤꯚ ꯅꯤꯌꯃꯁꯤꯡꯅ ꯃꯁꯤ ꯍꯣꯡꯍꯜꯂꯤ꯫ ꯄ꯭ꯂꯥꯟ ꯑꯁꯤ ꯑꯃꯁꯨꯡ ꯗꯦꯇꯥ ꯁꯤꯠ ꯅꯍꯥꯛꯀꯤ ꯑꯦꯀꯥꯎꯟꯇꯦꯟꯇꯇ ꯄꯤꯕꯤꯌꯨ꯫",
  "it.b6": "ꯊꯤꯗꯕ: ꯁꯔꯆꯥꯔꯖ, ꯁ꯭ꯄꯦꯁꯤꯌꯦꯜ ꯔꯦꯇꯇ ꯀꯦꯄꯤꯇꯦꯜ ꯒꯦꯟ, ꯐꯣꯔꯦꯟ ꯇꯦꯛꯁ ꯔꯤꯂꯤꯐ, ꯃꯥꯏꯅꯔ ꯑꯃꯒꯤ ꯏꯅꯀꯃꯗ ꯇꯦꯛꯁ, ꯑꯃꯁꯨꯡ ꯊꯦꯡꯅ ꯐꯥꯏꯜ ꯇꯧꯕꯒꯤ ꯏꯟꯇꯔꯦꯁ꯭ꯠ꯫",
  "it.b7": "ꯀꯔꯤꯁꯨ ꯐꯥꯏꯜ ꯇꯧꯗꯦ ꯑꯃꯁꯨꯡ ꯅꯍꯥꯛꯀꯤ ꯂꯥꯏꯔꯤꯛꯇ ꯀꯔꯤꯁꯨ ꯄꯣꯁ꯭ꯠ ꯇꯧꯗꯦ꯫",
